 "content": "def transform(grid):
    # Count separate horizontal bars of each non-background color and encode
    # those counts as cells, with color 3 first and color 2 second.
    colors = [c for row in grid for c in row]
    bg = max(set(colors), key=colors.count)
    counts = {}
    for row in grid:
        c = 0
        while c < len(row):
            if row[c] == bg:
                c += 1
                continue
            color = row[c]
            counts[color] = counts.get(color, 0) + 1
            while c < len(row) and row[c] == color:
                c += 1
    vals = [3] * counts.get(3, 0) + [2] * counts.get(2, 0)
    vals = (vals + [0] * 6)[:6]
    return [vals[:3], vals[3:]]
